package com.bechir.system;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import android.text.*;import java.util.*;
public class MainActivity extends Activity {
 LinearLayout root,grid; EditText search; TextClock clock;
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
 GradientDrawable bg(int c,int radius){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(radius));return d;}
 TextView label(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.WHITE);t.setGravity(17);return t;}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xff071321);getWindow().setNavigationBarColor(0xff071321);
 root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(16),dp(18),dp(16),dp(12));root.setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xff071321,0xff102e50,0xff071321}));setContentView(root);
 root.addView(label("BECHIR SYSTEM",20));clock=new TextClock(this);clock.setFormat24Hour("HH:mm");clock.setFormat12Hour("HH:mm");clock.setTextSize(64);clock.setTextColor(0xff70caff);clock.setGravity(17);root.addView(clock);
 TextClock date=new TextClock(this);date.setFormat24Hour("EEEE، dd MMMM");date.setFormat12Hour("EEEE، dd MMMM");date.setTextColor(Color.WHITE);date.setGravity(17);root.addView(date);
 Button home=new Button(this);home.setText("تعيين الواجهة الرئيسية");home.setOnClickListener(v->{try{startActivity(new Intent(android.provider.Settings.ACTION_HOME_SETTINGS));}catch(Exception e){}});root.addView(home);
 search=new EditText(this);search.setSingleLine(true);search.setHint("ابحث عن تطبيق");search.setTextColor(Color.WHITE);search.setHintTextColor(0xffaabbcc);search.setPadding(dp(16),dp(8),dp(16),dp(8));search.setBackground(bg(0xff203b55,20));root.addView(search,new LinearLayout.LayoutParams(-1,dp(50)));
 ScrollView scroll=new ScrollView(this);grid=new LinearLayout(this);grid.setOrientation(1);scroll.addView(grid);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
 search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){render();}public void afterTextChanged(Editable e){}});render();}
 protected void onResume(){super.onResume();if(grid!=null)render();}
 void render(){grid.removeAllViews();PackageManager pm=getPackageManager();Intent q=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER);List<ResolveInfo> apps=pm.queryIntentActivities(q,0);apps.sort((a,b)->a.loadLabel(pm).toString().compareToIgnoreCase(b.loadLabel(pm).toString()));LinearLayout row=null;int i=0;for(ResolveInfo a:apps){String name=a.loadLabel(pm).toString();if(a.activityInfo.packageName.equals(getPackageName())||!name.toLowerCase(Locale.ROOT).contains(search.getText().toString().toLowerCase(Locale.ROOT)))continue;if(i++%4==0){row=new LinearLayout(this);grid.addView(row);}LinearLayout tile=new LinearLayout(this);tile.setOrientation(1);tile.setGravity(17);tile.setPadding(dp(3),dp(10),dp(3),dp(10));row.addView(tile,new LinearLayout.LayoutParams(0,dp(100),1));ImageView icon=new ImageView(this);icon.setImageDrawable(a.loadIcon(pm));tile.addView(icon,new LinearLayout.LayoutParams(dp(48),dp(48)));TextView title=label(name,12);title.setMaxLines(2);tile.addView(title);tile.setOnClickListener(v->{try{Intent launch=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setClassName(a.activityInfo.packageName,a.activityInfo.name).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(launch);}catch(Exception e){Toast.makeText(this,"تعذر فتح التطبيق",0).show();}});}if(row!=null)while(i++%4!=0)row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));}
}